@staticmethod
def _grid_position(position: tuple[float, float]) -> tuple[int, int]:
    return floor(position[0] + 0.5), floor(position[1] + 0.5)

@staticmethod
def _skill(operator: RuntimeOperator) -> SyntheticSkill | None:
